INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES ("2024/03/31 12:00:00", 0.0, 129901, 10142, 100, 24, 7, 100, "2030/12/17 14:59:59", 10.85, "訓練成功、おめでとうございます\n褒めるべき時にはしっかり褒めるのも\n教官の務めですものね。それとも、\n罵られる方が好みですか？　クスクス", "エリコ", 0.0, 1);
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES ("2024/03/31 12:00:00", 0.0, 129901, 10142, 101, 24, 2, 101, "2030/12/17 14:59:59", 11.15, "厳しい訓練も、終わってみれば\n短く感じるものですわね。\n正直、私は暴れ足りないくらい…\nいえ、何でもありませんわ。クスクス", "エリコ", 0.0, 1);
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES ("2024/03/31 12:00:00", 0.0, 129901, 10142, 102, 24, 5, 102, "2030/12/17 14:59:59", 6.4, "行く手を阻む忌々しい邪魔者を\n蹴散らして、見事ゴールイン…！\nまるで私とあのおかたの人生を\n象徴するような道のりでした…", "エリコ", 0.0, 7);
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES ("2024/03/31 12:00:00", 0.0, 129901, 10142, 103, 24, 3, 103, "2030/12/17 14:59:59", 0.0, "まったくもって不甲斐ない結果です\nしかし、挽回の機会はまだありますわ\n次はゴミ虫の地位から脱却できるよう\n死力を尽くしなさい。いいですね？", "エリコ", 0.0, 3);
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES ("2024/03/31 12:00:00", 0.0, 129901, 10142, 104, 24, 8, 104, "2030/12/17 14:59:59", 2.43, "クスクス…ああご心配なさらず\nなんとも情けない成績を残す輩には\nどんな罰が相応しいか、考えている\nだけですので…クスクスクス", "エリコ", 0.0, 2);
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES ("2024/03/31 12:00:00", 0.0, 129901, 10142, 105, 24, 3, 105, "2030/12/17 14:59:59", 9.08, "私が教官として認められなければ、\nあのおかたを失望させてしまう…\nそれだけはあってはなりません\nあなた方も、わかっていますわね？", "エリコ", 0.0, 4);
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES ("2024/03/31 12:00:00", 0.0, 129901, 10142, 106, 24, 6, 106, "2030/12/17 14:59:59", 0.0, "まずまずの結果ではありますが、\nこの程度で満足してもらっては\n困りますわ。エリコ班の一員として、\nより高みを目指していただきますので", "エリコ", 0.0, 6);
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES ("2024/03/31 12:00:00", 0.0, 129901, 10142, 107, 24, 8, 107, "2030/12/17 14:59:59", 10.6, "私の指導を受けながら、この結果は…\nもっと真剣に考えねばなりませんね\nあなた方が怠けずにいるには、\nどんなしつけが必要かを…クスクス", "エリコ", 0.0, 3);
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES ("2024/03/31 12:00:00", 0.0, 129901, 10142, 108, 24, 4, 108, "2030/12/17 14:59:59", 7.54, "ひとまず訓練をこなしたご褒美か、\n実力を出しきれたとは言えない罰か…\nみなさんにどちらを与えるべきか\n少し悩む結果ですわね", "エリコ", 0.0, 6);
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES ("2024/03/31 12:00:00", 0.0, 129901, 10142, 109, 24, 7, 109, "2030/12/17 14:59:59", 11.5, "なかなかいい戦いぶりでしたわ\nこれもあなた方の頑張りと、何より\n優秀な教官である私の教育の賜物\nそうですわね？　クスクスクス…", "エリコ", 0.0, 2);
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES ("2024/03/31 12:00:00", 0.0, 129901, 10142, 110, 24, 1, 110, "2030/12/17 14:59:59", 8.83, "これだけ進めたのならば合格点ですわ\nでも、もっと高みを目指したいと\n思っているのなら…さらなる訓練にも\n付き合って差し上げましょう", "エリコ", 0.0, 2);
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES ("2024/03/31 12:00:00", 0.0, 129901, 10142, 111, 24, 2, 111, "2030/12/17 14:59:59", 6.68, "未熟で頼りなかったあなた方が、\n見違えるように成長しました\nなるほど…これこそが、教官冥利に\n尽きるという気持ちなのですね", "エリコ", 0.0, 1);
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES ("2024/03/31 12:00:00", 0.0, 129901, 10142, 112, 24, 2, 112, "2030/12/17 14:59:59", 8.8, "まさかあなた方が、私の予想すら\n超える力を発揮するとは…驚きました\nもはやゴミ虫などではありません\n一人前の騎士として胸を張りなさい", "エリコ", 0.0, 6);
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES ("2024/03/31 12:00:00", 0.0, 129901, 10142, 113, 24, 1, 113, "2030/12/17 14:59:59", 8.9, "クスクス、見事な働きです\nみなさんならできると信じていました\n他でもない私の指導を受けた、\nエリコ班の優秀な新兵なのですから", "エリコ", 0.0, 2);
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES ("2024/03/31 12:00:00", 0.0, 129901, 10142, 114, 24, 5, 114, "2030/12/17 14:59:59", 3.7, "なんてすばらしい成績…！\n今日という日は『あのおかたを想い\nエリコが限界を超えた記念日』として\n歴史に刻まれることでしょう…！", "エリコ", 0.0, 2);
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES ("2024/03/31 12:00:00", 0.0, 129801, 10142, 200, 24, 2, 200, "2030/12/17 14:59:59", 7.6, "よし、いい訓練になったな\nおまえたちもよく動けてたし、\nちゃんと成長できてると思うぜ\nその調子で頑張れよっ", "マコト", 0.0, 1);
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES ("2024/03/31 12:00:00", 0.0, 129801, 10142, 201, 24, 1, 201, "2030/12/17 14:59:59", 2.25, "ひとまずゴールおめでとう！\nでも、努力は継続してこそだからな\nおまえたちにやる気があるなら、\n何度だって付き合ってやるよ", "マコト", 0.0, 2);
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES ("2024/03/31 12:00:00", 0.0, 129801, 10142, 202, 24, 1, 202, "2030/12/17 14:59:59", 3.28, "行軍訓練はこれにて完了！\n…なーんて思ってないよな？\n学んだことが体に染みつくまで\n地道に繰り返すのが練習ってもんさ", "マコト", 0.0, 2);
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES ("2024/03/31 12:00:00", 0.0, 129801, 10142, 203, 24, 1, 203, "2030/12/17 14:59:59", 2.98, "みんなに無理をさせちまったか…\nでもこれで諦めることはないぜ\n次はきっとうまくいく。そう信じて\n鍛え続ければ、道は開けるはずだ！", "マコト", 0.0, 4);
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES ("2024/03/31 12:00:00", 0.0, 129801, 10142, 204, 24, 1, 204, "2030/12/17 14:59:59", 3.0, "こいつは悔しい結果だな…\nま、反省点はいろいろあったし\nひとつずつ乗り越えていこう\nあたしたちで力を合わせて、なっ！", "マコト", 0.0, 4);
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES ("2024/03/31 12:00:00", 0.0, 129801, 10142, 205, 24, 2, 205, "2030/12/17 14:59:59", 10.3, "おまえたちはまだ未熟な訓練兵、\n失敗を必要以上に悔やむことはねえよ\nでも実戦じゃこうはいかないからな\n次は気合を入れ直していけよっ！", "マコト", 0.0, 1);
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES ("2024/03/31 12:00:00", 0.0, 129801, 10142, 206, 24, 1, 206, "2030/12/17 14:59:59", 2.93, "これがおまえたちの全力？\nいやいや、そんなはずはないよなっ\nおまえらならもっと強くなれる！\nあたしが言うんだ、間違いないぜ！", "マコト", 0.0, 6);
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES ("2024/03/31 12:00:00", 0.0, 129801, 10142, 207, 24, 1, 207, "2030/12/17 14:59:59", 9.3, "おまえたちの実力を考えりゃ、\nベストを尽くせたとは言えない成績だ\nなら、次やるべきことも決まってる\n気持ちを切り替えて、鍛え直すんだ！", "マコト", 0.0, 3);
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES ("2024/03/31 12:00:00", 0.0, 129801, 10142, 208, 24, 1, 208, "2030/12/17 14:59:59", 6.9, "まだまだ課題がある内容だったな～\n無駄な動き、判断の遅れ…\nそういうのをしっかり直していけば、\n記録ももっと伸びるはずだっ", "マコト", 0.0, 4);
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES ("2024/03/31 12:00:00", 0.0, 129801, 10142, 209, 24, 2, 209, "2030/12/17 14:59:59", 0.0, "ここまでいけりゃ、合格点！\nむしろ、最初の頼りなさを思えば\nすげえ成長してるんじゃねえか？\n胸を張れる結果だと思うぜっ！", "マコト", 0.0, 2);
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES ("2024/03/31 12:00:00", 0.0, 129801, 10142, 210, 24, 2, 210, "2030/12/17 14:59:59", 5.95, "なかなかハードな訓練だったけど、\nみんなしっかりついてこられたな\n地道に続けた基礎トレの成果が\n形になってる、その証だぜっ", "マコト", 0.0, 1);
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES ("2024/03/31 12:00:00", 0.0, 129801, 10142, 211, 24, 1, 211, "2030/12/17 14:59:59", 6.73, "今回の訓練もよく頑張ったな！\nしっかり休んで次に備えろよ！\nなんつーか、教え子が成長してくのを\n見るのは楽しいもんだな…", "マコト", 0.0, 2);
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES ("2024/03/31 12:00:00", 0.0, 129801, 10142, 212, 24, 2, 212, "2030/12/17 14:59:59", 0.0, "おまえら、すげえじゃねえか！\nこれならもう、ひよっこ新兵なんて\n言えねえな。きっと騎士団でも\n大活躍間違いなしだぜ！", "マコト", 0.0, 2);
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES ("2024/03/31 12:00:00", 0.0, 129801, 10142, 213, 24, 2, 213, "2030/12/17 14:59:59", 6.65, "敵との戦い方、状況判断の正確さ\n何より根性…どれも最高だったぞ！\nうかうかしてたら、教官のあたしまで\n追い抜かれちまうかもな…へへっ", "マコト", 0.0, 1);
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES ("2024/03/31 12:00:00", 0.0, 129801, 10142, 214, 24, 1, 214, "2030/12/17 14:59:59", 3.05, "あたしの指導が良かった？\nいやいや、ここまで強くなれたのは、\n他でもないおまえたち自身が努力した\nおかげだよ。改めて…おめでとうっ！", "マコト", 0.0, 6);
